<?php
declare(strict_types=1);
require __DIR__.'/../app/bootstrap.php';require_admin();
$db=database();$activity=admin_activity($db);$activityId=(int)$activity['id'];$formId=(int)($_GET['form']??0);$sql='SELECT s.*,f.title form_title FROM cms_form_submissions s JOIN cms_forms f ON f.id=s.form_id WHERE s.activity_id=?';$args=[$activityId];if($formId){$sql.=' AND s.form_id=?';$args[]=$formId;}$sql.=' ORDER BY s.created_at ASC';$q=$db->prepare($sql);$q->execute($args);$rows=$q->fetchAll();$fieldKeys=[];$labels=[];foreach($rows as $row){$snapshot=json_decode((string)$row['form_snapshot_json'],true)?:[];foreach($snapshot['fields']??[] as $field){$key=(string)($field['id']??'');if($key!==''&&!in_array($key,$fieldKeys,true))$fieldKeys[]=$key;if($key!==''&&!isset($labels[$key]))$labels[$key]=(string)($field['label']??$key);}}
header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="respostas-workshop-'.gmdate('Ymd-His').'.csv"');echo "\xEF\xBB\xBF";$out=fopen('php://output','wb');fputcsv($out,array_merge(['Data','Formulário','Idioma','Status'],array_map(fn($key)=>$labels[$key]??$key,$fieldKeys)),',','"','\\');foreach($rows as $row){$payload=json_decode((string)$row['payload_json'],true)?:[];$line=[$row['created_at'],$row['form_title'],$row['locale'],$row['status']];foreach($fieldKeys as $key){$value=$payload[$key]??'';$line[]=is_array($value)?implode(' | ',$value):(string)$value;}fputcsv($out,$line,',','"','\\');}fclose($out);exit;
